<?php
$admin_title='Sales & Receipts';include '_header.php';
$pdo->exec("CREATE TABLE IF NOT EXISTS sales(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,receipt_no VARCHAR(60) NOT NULL UNIQUE,total DECIMAL(12,2) NOT NULL,payment_method VARCHAR(40) NOT NULL,customer_name VARCHAR(160),user_id INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$pdo->exec("CREATE TABLE IF NOT EXISTS sale_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sale_id BIGINT UNSIGNED NOT NULL,product_id INT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(12,2) NOT NULL,line_total DECIMAL(12,2) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_ok($_POST['csrf']??''))$msg='Security token expired.';else{$pid=(int)($_POST['product_id']??0);$qty=(int)($_POST['quantity']??0);$method=trim($_POST['payment_method']??'Cash');$customer=trim($_POST['customer_name']??'');try{if($pid<1||$qty<1)throw new Exception('Choose a product and quantity greater than zero.');$pdo->beginTransaction();$q=$pdo->prepare('SELECT * FROM products WHERE id=? AND status="active" FOR UPDATE');$q->execute([$pid]);$prod=$q->fetch();if(!$prod)throw new Exception('Product not found.');if($prod['quantity']<$qty)throw new Exception('Insufficient stock. Available: '.$prod['quantity']);$total=$qty*(float)$prod['selling_price'];$receipt='SALE-'.date('Ymd-His').'-'.random_int(100,999);$pdo->prepare('INSERT INTO sales(receipt_no,total,payment_method,customer_name,user_id) VALUES(?,?,?,?,?)')->execute([$receipt,$total,$method,$customer,admin_user()['id']??null]);$sid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,line_total) VALUES(?,?,?,?,?)')->execute([$sid,$pid,$qty,$prod['selling_price'],$total]);$after=(int)$prod['quantity']-$qty;$pdo->prepare('UPDATE products SET quantity=? WHERE id=?')->execute([$after,$pid]);$pdo->prepare('INSERT INTO stock_transactions(product_id,type,quantity,stock_before,stock_after,reason,reference_no,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$pid,'OUT',$qty,$prod['quantity'],$after,'Sale',$receipt,admin_user()['id']??null]);$pdo->commit();$msg='Sale recorded. Receipt: '.$receipt.' | Total: K'.number_format($total,2);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$msg=$e->getMessage();}}}
$products=$pdo->query("SELECT id,name,sku,quantity,unit,selling_price FROM products WHERE status='active' ORDER BY name")->fetchAll();$sales=$pdo->query('SELECT s.*,u.name user_name FROM sales s LEFT JOIN users u ON u.id=s.user_id ORDER BY s.id DESC LIMIT 100')->fetchAll();?>
<?php if($msg):?><div class="panel"><b><?=e($msg)?></b></div><?php endif;?>
<div class="panel"><div class="panel-head"><h2>Record a Sale</h2><small class="muted">Stock is deducted only after a sale is saved.</small></div><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><div class="form-grid"><div class="form-group"><label>Product *</label><select class="form-control" name="product_id" required><option value="">Choose product</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?> (<?=e($x['sku'])?>) — <?=$x['quantity']?> <?=e($x['unit'])?> available · K<?=number_format($x['selling_price'],2)?></option><?php endforeach;?></select></div><div class="form-group"><label>Quantity *</label><input class="form-control" type="number" min="1" name="quantity" required></div><div class="form-group"><label>Payment method</label><select class="form-control" name="payment_method"><option>Cash</option><option>Mobile Money</option><option>Card</option><option>Bank Transfer</option><option>Credit</option></select></div><div class="form-group"><label>Customer (optional)</label><input class="form-control" name="customer_name"></div></div><p><button class="btn btn-primary">Complete Sale & Generate Receipt Number</button></p></form></div>
<div class="panel"><div class="panel-head"><h2>Recent Sales</h2><button class="btn btn-ghost" onclick="window.print()" type="button">Print</button></div><div class="table-wrap"><table><thead><tr><th>Receipt</th><th>Date</th><th>Customer</th><th>Payment</th><th>Total</th><th>Recorded by</th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td><?=e($s['receipt_no'])?></td><td><?=e($s['created_at'])?></td><td><?=e($s['customer_name'])?></td><td><?=e($s['payment_method'])?></td><td>K<?=number_format($s['total'],2)?></td><td><?=e($s['user_name'])?></td></tr><?php endforeach;?><?php if(!$sales):?><tr><td colspan="6">No sales recorded yet.</td></tr><?php endif;?></tbody></table></div></div><?php include '_footer.php';?>